-- Canonical ordered block stream for every existing Human Archive record.
begin;
alter table public.human_archive_record_structures add column if not exists blocks jsonb not null default '[]'::jsonb;
alter table public.human_archive_record_structures drop constraint if exists human_archive_record_structures_blocks_array_check;
alter table public.human_archive_record_structures add constraint human_archive_record_structures_blocks_array_check check (jsonb_typeof(blocks) = 'array');
on conflict (record_id) do update set blocks = excluded.blocks;
create or replace function public.save_human_archive_record_blocks_v1(p_record_id bigint, p_blocks jsonb, p_expected_updated_at timestamptz default null)
returns timestamptz language plpgsql security invoker set search_path = pg_catalog, public as $$
declare v_updated_at timestamptz;
begin
 if auth.uid() is null or not exists (select 1 from public.vha_cms_admins admin where admin.user_id = auth.uid()) then raise exception 'CMS admin access required' using errcode = '42501'; end if;
 if p_record_id is null or p_record_id <= 0 then raise exception 'A valid archive record ID is required' using errcode = '22023'; end if;
 if p_blocks is null or jsonb_typeof(p_blocks) <> 'array' then raise exception 'Blocks must be a JSON array' using errcode = '22023'; end if;
 update public.human_archive_record_structures set blocks = p_blocks, updated_at = now(), updated_by = auth.uid() where record_id = p_record_id and (p_expected_updated_at is null or updated_at = p_expected_updated_at) returning updated_at into v_updated_at;
 if found then return v_updated_at; end if;
 if exists (select 1 from public.human_archive_record_structures where record_id = p_record_id) then raise exception 'Archive record changed in another session' using errcode = '40001'; end if;
 if p_expected_updated_at is not null then raise exception 'Archive record structure is missing' using errcode = '40001'; end if;
 return v_updated_at;
end; $$;
revoke all on function public.save_human_archive_record_blocks_v1(bigint,jsonb,timestamptz) from public, anon, service_role;
grant execute on function public.save_human_archive_record_blocks_v1(bigint,jsonb,timestamptz) to authenticated;
commit;
